// Replays testdata/deployment_vectors.json, generated by Go's
// TestDeploymentVectors: the deployment key names state on disk, so the two
// SDKs disagreeing on it strands each other's journals and catalogs.

import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'

import { catalogStorageKey } from '../src/assemble.js'
import { ZsError } from '../src/errors.js'
import { type Network, type NetworkName, type Rail, feeUnitOf, ownsRecord, resolveNetwork } from '../src/network.js'

interface Input {
    rail?: Rail
    network?: string
    endpoint?: string
    token?: string
    escrow_app_id?: number
}

const vectors = JSON.parse(readFileSync(new URL('../../testdata/deployment_vectors.json', import.meta.url), 'utf8')) as {
    resolve: { name: string; input: Input; error?: string; rail?: string; label?: string; key?: string; legacy_key?: string }[]
    scope: { name: string; input: Input; rows: { deployment: string; escrow_app_id: number; owns: boolean }[] }[]
}

function networkOf(in_: Input): Network {
    const n: Network = {}
    if (in_.rail !== undefined) n.rail = in_.rail
    if (in_.network !== undefined) n.network = in_.network as NetworkName
    if (in_.endpoint !== undefined) n.algodEndpoint = in_.endpoint
    if (in_.token !== undefined) n.algodToken = in_.token
    if (in_.escrow_app_id !== undefined) n.escrowAppId = BigInt(in_.escrow_app_id)
    return n
}

describe('deployment vectors', () => {
    for (const c of vectors.resolve) {
        it(`resolves: ${c.name}`, () => {
            if (c.error) {
                let err: unknown
                try {
                    resolveNetwork(networkOf(c.input))
                } catch (e) {
                    err = e
                }
                expect(err).toBeInstanceOf(ZsError)
                expect((err as ZsError).code).toBe(c.error)
                return
            }
            const d = resolveNetwork(networkOf(c.input))
            expect([d.rail, d.label, d.key, d.legacyKey]).toEqual([c.rail, c.label, c.key, c.legacy_key])
        })
    }

    for (const s of vectors.scope) {
        it(`scopes journal rows: ${s.name}`, () => {
            const d = resolveNetwork(networkOf(s.input))
            for (const r of s.rows) {
                const rec = { escrowAppId: BigInt(r.escrow_app_id), ...(r.deployment ? { deployment: r.deployment } : {}) }
                expect(ownsRecord(d, rec), JSON.stringify(r)).toBe(r.owns)
            }
        })
    }

    it('treats an empty deployment as a row from before rows named one', () => {
        const d = resolveNetwork({ network: 'localnet', escrowAppId: 7n })
        expect(ownsRecord(d, { deployment: '', escrowAppId: 7n })).toBe(true)
    })

    it('claims an unnamed row by its app id only on Algorand', () => {
        const d = { ...resolveNetwork({ network: 'localnet', escrowAppId: 7n }), rail: 'solana' as Rail }
        expect(ownsRecord(d, { escrowAppId: 7n })).toBe(false)
    })
})

describe('feeUnitOf', () => {
    // Literal, as Go's TestFeeUnitOf: the decimals scale every fee's USD figure.
    it('is ALGO in micro-units on Algorand and SOL in lamports on Solana', () => {
        expect(feeUnitOf('algorand')).toEqual({ currency: 'ALGO', decimals: 6 })
        expect(feeUnitOf('solana')).toEqual({ currency: 'SOL', decimals: 9 })
    })
})

describe('catalogStorageKey', () => {
    it('names the catalog by the deployment key, or by a key given as text', () => {
        const d = resolveNetwork({ network: 'testnet' })
        expect(catalogStorageKey(d)).toBe('zs.catalog.algorand-testnet-765860477')
        expect(catalogStorageKey(d.legacyKey)).toBe('zs.catalog.765860477')
    })
})
